import { notFound } from "next/navigation";
import { PORTFOLIO_DETAILS } from "@/lib/constants/portfolio-details";
import { createMetadata } from "@/lib/seo/metadata";
import { CaseStudyHero } from "@/components/our-works-detail/case-study-hero";
import { CaseStudyContent } from "@/components/our-works-detail/case-study-content";
import { CaseStudyGallery } from "@/components/our-works-detail/case-study-gallery";
import { CtaBanner } from "@/components/shared/cta-banner";
import layoutStyles from "./case-study-layout.module.css";

export function generateStaticParams() {
  return PORTFOLIO_DETAILS.map((d) => ({ slug: d.slug }));
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const detail = PORTFOLIO_DETAILS.find((d) => d.slug === slug);
  if (!detail) return {};
  return createMetadata({
    title: `${detail.title} | Case Study | Boldteq`,
    description: `${detail.challenge.slice(0, 155)}...`,
    path: `/our-works/${detail.slug}`,
    ogImage: detail.gallery[0],
  });
}

export default async function CaseStudyPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const detail = PORTFOLIO_DETAILS.find((d) => d.slug === slug);
  if (!detail) notFound();

  return (
    <>
      <CaseStudyHero detail={detail} />
      <div className={layoutStyles.grid}>
        <CaseStudyContent detail={detail} />
        <CaseStudyGallery images={detail.gallery} title={detail.title} />
      </div>
      <CtaBanner />
    </>
  );
}

"use client";

import { useEffect, useCallback } from "react";
import Image from "next/image";
import type { PortfolioItem } from "@/types/portfolio";
import styles from "./portfolio-popup.module.css";

interface PortfolioPopupProps {
  item: PortfolioItem;
  onClose: () => void;
}

export function PortfolioPopup({ item, onClose }: PortfolioPopupProps) {
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    },
    [onClose]
  );

  useEffect(() => {
    document.addEventListener("keydown", handleKeyDown);
    document.body.style.overflow = "hidden";

    return () => {
      document.removeEventListener("keydown", handleKeyDown);
      document.body.style.overflow = "";
    };
  }, [handleKeyDown]);

  // Full content mode for items with detail pages, gallery/image mode for others
  const isFullMode = item.hasDetailPage;
  const containerClass = isFullMode
    ? styles.container
    : `${styles.container} ${styles.containerGallery}`;

  return (
    <div
      className={styles.overlay}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
      role="dialog"
      aria-modal="true"
      aria-label={`${item.name} project details`}
    >
      <div className={containerClass}>
        <button
          type="button"
          className={styles.closeBtn}
          onClick={onClose}
          aria-label="Close popup"
        >
          &times;
        </button>

        {isFullMode ? (
          <iframe
            src={`/our-works/${item.slug}`}
            className={styles.iframe}
            title={`${item.name} project details`}
            allowFullScreen
          />
        ) : (
          <div className={styles.galleryContent}>
