/* ============================================================
   PortfolioPopup — matches Webflow .global-popup exactly
   ============================================================ */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 999999;
  background-color: rgba(15, 23, 42, 0.65);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: fadeIn 0.2s ease;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Full-content mode container */
.container {
  position: relative;
  background-color: #fff;
  border-radius: 24px;
  width: 100%;
  max-width: 1280px;
  min-height: 600px;
  max-height: 600px;
  display: grid;
  grid-template-rows: auto;
  grid-template-columns: 1fr;
  overflow: hidden;
  animation: slideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  margin-left: auto;
  margin-right: auto;
  flex: 1;
}

@keyframes slideUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Gallery mode — narrower */
.containerGallery {
  max-width: 600px;
  min-height: auto;
  max-height: 85vh;
}

/* Close button */
.closeBtn {
  position: absolute;
  top: 20px;
  right: 20px;
  z-index: 11;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 25px;
  height: 25px;
  background-image: linear-gradient(#21cfff, #019ae6);
  border-radius: 5px;
  border: none;
  color: #fff;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 25px;
  line-height: 30px;
  cursor: pointer;
  transition: filter 0.15s ease;
}

.closeBtn:hover {
  filter: brightness(1.1);
}

/* Iframe for full content mode */
.iframe {
  width: 100%;
  height: 100%;
  border: none;
  border-radius: 0 0 24px 24px;
  min-height: 560px;
}

/* Gallery mode content (image + info) */
.galleryContent {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.galleryImageWrap {
  position: relative;
  width: 100%;
  flex: 1;
  min-height: 400px;
  border-radius: 24px 24px 0 0;
  overflow: hidden;
}

.galleryImage {
  object-fit: cover;
  object-position: 50% 0%;
}

.galleryInfo {
  padding: 20px 24px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.galleryTitle {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 20px;
  font-weight: 700;
  color: #082753;
  margin: 0;
}

.galleryBadge {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 12px;
  font-weight: 500;
  color: #082753;
  background-color: #f0f7ff;
  border-radius: 8px;
  padding: 4px 10px;
  text-transform: capitalize;
}

